def eligible(entries, required_features):
    """Return entries safe for the requested feature set."""
    result = []
    for entry in entries:
        if not entry.get("enabled", True):
            continue
        if entry.get("expired", False):
            continue
        price = entry.get("price")
        # price must be numeric zero, not bool
        if isinstance(price, bool) or not isinstance(price, (int, float)) or price != 0:
            continue
        features = entry.get("features", [])
        if not all(feature in features for feature in required_features):
            continue
        result.append(entry)
    return result
